416	// Re-posting an existing identity with a null member is invalid input whether
417	// the stored value is an empty string or a non-empty string, and regardless of
418	// which member is null. It must surface the same 400 (never 200 or 409) and must
419	// leave the committed record, its order and its conflict flag untouched.
420	func TestPostNetPolicyNullMemberOnExistingIdentity(t *testing.T) {
421		cases := []struct {
422			name        string
423			seedParams  string
424			retryParams string
425		}{
426			{
427				name:        "stored empty string retried as null",
428				seedParams:  `{"mode": ""}`,
429				retryParams: `{"mode": null}`,
430			},
431			{
432				name:        "stored non-empty string retried as null",
433				seedParams:  `{"mode": "enforce"}`,
434				retryParams: `{"mode": null}`,
435			},
436			{
437				name:        "second member null alongside legal string",
438				seedParams:  `{"mode": "enforce", "retries": "3"}`,
439				retryParams: `{"mode": "enforce", "retries": null}`,
440			},
441			{
442				name:        "first member null alongside legal string",
443				seedParams:  `{"mode": "enforce", "retries": "3"}`,
444				retryParams: `{"retries": "3", "mode": null}`,
445			},
446		}
447		for _, tc := range cases {
448			t.Run(tc.name, func(t *testing.T) {
449				router, _ := newTestRouter(t)
